installer-gui-script.script:

function ntfsmacCheck() {
    if (!system.files.fileExistsAtPath('/Library/Filesystems/macfuse.fs')) {
        my.result.type = 'Fatal';
        my.result.title = 'macFUSE is required';
        my.result.message = 'Install macFUSE 5.5.0 or newer and turn it on in System Settings, then run this installer again. ntfs-macos does not bundle macFUSE.';
        return false;
    }
    return true;
}
